      --color-accent-strong: #0b5f59;
      --color-danger: #b42318;
      --shadow: 0 18px 50px rgba(23, 32, 51, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    html {
      color-scheme: light;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--color-text);
      background:
        radial-gradient(circle at top, #eaf1ff 0, transparent 38%),
        var(--color-bg);
    }

