      margin-bottom: 0.75rem;
      padding: 0;
      font-weight: 700;
      font-size: 1.0625rem;
    }

    .required {
      color: var(--color-danger);
      font-weight: 700;
    }

    .hint {
      margin: 0 0 1rem;
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

