      font-weight: 700;
    }

    .hint {
      margin: 0 0 1rem;
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .radio-list {
      display: grid;
      gap: 0.75rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      border: 1px solid var(--color-border);
