<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <main id="maincontent" tabindex="-1">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose one way you'd like to receive updates from us.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help">
            <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
            <p class="hint" id="notification-help">Select a single answer so we can tailor your alerts.</p>

            <div class="radio-list">
              <label class="radio-option" for="notification-email">
                <input id="notification-email" name="notification-preference" type="radio" value="email" required>
                <span class="radio-label">
                  <strong>Email</strong>
                  <span>Receive updates in your inbox.</span>
                </span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input id="notification-sms" name="notification-preference" type="radio" value="sms" required>
                <span class="radio-label">
                  <strong>SMS</strong>
                  <span>Get text messages on your phone.</span>
                </span>
              </label>

              <label class="radio-option" for="notification-push">
                <input id="notification-push" name="notification-preference" type="radio" value="push" required>
                <span class="radio-label">
                  <strong>Push Notifications</strong>
                  <span>See alerts directly in the app.</span>
                </span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Save preference</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const status = document.getElementById('form-status');
    const radios = form.querySelectorAll('input[name="notification-preference"]');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const selected = form.querySelector('input[name="notification-preference"]:checked');

      if (!selected) {
        status.textContent = 'Error: Choose one notification preference before saving.';
        status.dataset.state = 'error';
        radios[0].focus();
        return;
      }

      const label = form.querySelector(`label[for="${selected.id}"] strong`)?.textContent || selected.value;
      status.textContent = `Saved: ${label}.`;
      status.dataset.state = 'success';
    });
  </script>
</body>
</html>
