<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Notification Preferences</title>
  <style>
    :root {
      --color-bg: #f4f7fb;
      --color-surface: #ffffff;
      --color-text: #172033;
      --color-muted-text: #5d6b82;
      --color-border: #ccd5e1;
      --color-focus: #2f6feb;
      --color-accent: #0f766e;
      --color-accent-strong: #0b5f59;
      --color-danger: #b42318;
      --shadow: 0 18px 50px rgba(23, 32, 51, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    html {
      color-scheme: light;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--color-text);
      background:
        radial-gradient(circle at top, #eaf1ff 0, transparent 38%),
        var(--color-bg);
    }

    a {
      color: var(--color-accent);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      background: var(--color-surface);
      border: 2px solid var(--color-focus);
      border-radius: 0.75rem;
      transform: translateY(-160%);
      transition: transform 160ms ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: none;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 5rem 1rem 2rem;
    }

    .card {
      width: min(100%, 40rem);
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 4vw, 2.25rem);
    }

    h1 {
      margin: 0 0 0.5rem;
      font-size: clamp(1.75rem, 3vw, 2.25rem);
      line-height: 1.15;
      letter-spacing: -0.03em;
    }

    .intro {
      margin: 0 0 1.5rem;
      color: var(--color-muted-text);
      max-width: 34rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      margin: 0;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
      min-inline-size: 0;
    }

    legend {
      margin-bottom: 0.75rem;
      padding: 0;
      font-weight: 700;
      font-size: 1.0625rem;
    }

    .required {
      color: var(--color-danger);
      font-weight: 700;
    }

    .hint {
      margin: 0 0 1rem;
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .radio-list {
      display: grid;
      gap: 0.75rem;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      border: 1px solid var(--color-border);
      border-radius: 1rem;
      padding: 0.95rem 1rem;
      background: linear-gradient(180deg, #fff, #fbfcfe);
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    .radio-option:hover {
      border-color: #9eb0c9;
    }

    .radio-option:focus-within {
      border-color: var(--color-focus);
      box-shadow: 0 0 0 3px rgba(47, 111, 235, 0.18);
    }

    .radio-option:has(input:checked) {
      border-color: var(--color-accent);
      background: #f0fbfa;
    }

    input[type="radio"] {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0;
      accent-color: var(--color-accent);
      flex: 0 0 auto;
    }

    .radio-label {
      display: grid;
      gap: 0.125rem;
      cursor: pointer;
      flex: 1;
    }

    .radio-label strong {
      font-weight: 600;
    }

    .radio-label span {
      color: var(--color-muted-text);
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 0.9rem;
      padding: 0.95rem 1.25rem;
      font: inherit;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(180deg, var(--color-accent), var(--color-accent-strong));
      box-shadow: 0 12px 24px rgba(15, 118, 110, 0.22);
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 14px 28px rgba(15, 118, 110, 0.28);
    }

    button:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    .status {
      margin: 0;
      min-height: 1.5rem;
      color: var(--color-muted-text);
    }

    .status[data-state="success"] {
      color: var(--color-accent-strong);
      font-weight: 600;
    }

    .status[data-state="error"] {
      color: var(--color-danger);
      font-weight: 600;
    }

    @media (max-width: 30rem) {
      main {
        padding-top: 4rem;
      }

      .card {
        border-radius: 1.1rem;
      }

      .radio-option {
        align-items: flex-start;
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
